/**
 * mruby/c のバージョンを設定するための設定画面(ユーザー設定ダイアログの1タブ)
 **/
RED.mrubycSettings = (function() {

    var SETTING_KEY = "mrubyc.version";
    var AVAILABLE_VERSIONS = ["3.4.0", "4.0.0"];
    var DEFAULT_VERSION = "3.4.0";

    function getVersion() {
        var version = RED.settings.get(SETTING_KEY, DEFAULT_VERSION);
        if (AVAILABLE_VERSIONS.indexOf(version) === -1) {
            version = DEFAULT_VERSION;
        }
        return version;
    }

    function setVersion(version) {
        if (AVAILABLE_VERSIONS.indexOf(version) === -1) {
            version = DEFAULT_VERSION;
        }
        RED.settings.set(SETTING_KEY, version);
        return version;
    }

    function getSettingsPane() {
        var pane = $("<div/>", {
            id: "red-ui-settings-tab-mrubyc",
            class: "form-horizontal"
        });

        var content = $("<div/>", {
            class: "form-row"
        }).css({
            "margin": "10px"
        }).appendTo(pane);

        var label = $("<label></label>").css({
            width: "100%"
        }).appendTo(content);
        $("<i/>", { class: "fa fa-microchip" }).appendTo(label);
        $("<span/>").text(" mruby/c バージョン").appendTo(label);

        $("<p/>").css({
            color: "var(--red-ui-secondary-text-color)",
            "margin-bottom": "10px"
        }).text("マイコンへ書き込むmruby/cのバージョン").appendTo(content);

        var select = $("<select/>", {
            id: "red-ui-settings-mrubyc-version"
        }).css({ width: "200px" }).appendTo(content);

        AVAILABLE_VERSIONS.forEach(function(v) {
            $("<option/>", { value: v }).text(v).appendTo(select);
        });

        select.val(getVersion());

        return pane;
    }

    function init() {
        RED.userSettings.add({
            id: "mrubyc",
            title: "mruby/c",
            get: getSettingsPane,
            close: function() {
                var select = $("#red-ui-settings-mrubyc-version");
                if (select.length) {
                    setVersion(select.val());
                }
            }
        });
    }

    return {
        init: init,
        getVersion: getVersion,
        setVersion: setVersion
    };

})();
